      mape: sarimaConfig2?.mape || '6.8%',
      mae: sarimaConfig2?.mae !== undefined ? sarimaConfig2.mae.toFixed(2) : '0.09',
      isTrained: !!sarimaConfig2,
      badge: 'Candidate'
    },
    {
      option: 'Alternative LSTM',
      subtitle: 'Multi-Variate Weather Sequences',
      rmse: lstmMetrics?.rmse !== undefined ? lstmMetrics.rmse.toFixed(2) : '0.28',
      mape: lstmMetrics?.mape || '0.03%',
      mae: lstmMetrics?.mae !== undefined ? lstmMetrics.mae.toFixed(2) : '0.07',
      isTrained: !!lstmMetrics,
