        {/* Card 3: Hybrid Architecture Champion */}
        <div className="card" style={{ background: '#fafffa', borderRadius: '16px', padding: '20px', border: '2px solid #27ae60', boxShadow: '0 6px 20px rgba(39, 174, 96, 0.1)' }}>
